method file_name_check(file_name: string) returns (result: string)
    requires file_name != null
    requires file_name.Length > 0
    ensures result == "Yes" ==> 
        (CountDigits(file_name) <= 3 && 
         ContainsExactlyOneDot(file_name) && 
         IsValidBeforeDot(file_name) && 
         IsValidAfterDot(file_name)
        )
    ensures result == "No" ==> 
        !(CountDigits(file_name) <= 3 && 
          ContainsExactlyOneDot(file_name) && 
          IsValidBeforeDot(file_name) && 
          IsValidAfterDot(file_name)
        )

// Helper methods for preconditions and postconditions

function CountDigits(file_name: string): int
    reads []
    ensures 0 <= result <= file_name.Length
{
    var count := 0;
    var i := 0;
    while i < file_name.Length
        invariant 0 <= count <= i
    {
        if file_name[i] >= '0' && file_name[i] <= '9' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function ContainsExactlyOneDot(file_name: string): bool
    reads []
{
    var dotCount := 0;
    var i := 0;
    while i < file_name.Length
        invariant 0 <= dotCount <= i
    {
        if file_name[i] == '.' {
            dotCount := dotCount + 1;
        }
        i := i + 1;
    }
    return dotCount == 1;
}

function IsValidBeforeDot(file_name: string): bool
    reads []
{
    var dotIndex := -1;
    var i := 0;
    while i < file_name.Length
        invariant -1 <= dotIndex <= i
    {
        if file_name[i] == '.' {
            dotIndex := i;
        }
        i := i + 1;
    }
    if dotIndex <= 0 {
        return false;
    }
    return file_name[0] >= 'a' && file_name[0] <= 'z' || file_name[0] >= 'A' && file_name[0] <= 'Z';
}

function IsValidAfterDot(file_name: string): bool
    reads []
{
    var dotIndex := -1;
    var i := 0;
    while i < file_name.Length
        invariant -1 <= dotIndex <= i
    {
        if file_name[i] == '.' {
            dotIndex := i;
        }
        i := i + 1;
    }
    if dotIndex < 0 || dotIndex >= file_name.Length - 1 {
        return false;
    }
    var extension := file_name[dotIndex + 1 .. file_name.Length];
    return extension == "txt" || extension == "exe" || extension == "dll";
}
```

